import type { INode, INodeLinkedList } from "../model";
import type { IDisposable } from "./disposable";

export interface IHistoryRecord extends IDisposable {
    readonly name: string;
    undo(): void;
    redo(): void;
}

export class History implements IDisposable {
    private readonly _undos: IHistoryRecord[] = [];
    private readonly _redos: IHistoryRecord[] = [];

    disabled = false;
    undoLimits = 50;

    #isUndoing = false;
    get isUndoing() {
        return this.#isUndoing;
    }
    #isRedoing = false;
    get isRedoing() {
        return this.#isRedoing;
    }

    dispose(): void {
        this._redos.forEach((record) => record.dispose());
        this._undos.forEach((record) => record.dispose());
        this.clear();
    }

    private clear(): void {
        this._undos.length = 0;
        this._redos.length = 0;
    }

    add(record: IHistoryRecord) {
        if (this.disabled) return;

        this._redos.length = 0;
        this._undos.push(record);

        if (this._undos.length > this.undoLimits) {
            const removed = this._undos.shift();
            removed?.dispose();
        }
    }

    undoCount() {
        return this._undos.length;
    }

    redoCount() {
        return this._redos.length;
    }

    undo() {
        this.#isUndoing = true;
        this.tryOperate(
            () => {
                const record = this._undos.pop();
                if (!record) return;

                record.undo();
                this._redos.push(record);
            },
            () => {
                this.#isUndoing = false;
            },
        );
    }

    redo() {
        this.#isRedoing = true;
        this.tryOperate(
            () => {
                const record = this._redos.pop();
                if (!record) return;

                record.redo();
                this._undos.push(record);
            },
            () => {
                this.#isRedoing = false;
            },
        );
    }

    private tryOperate(action: () => void, onFinally: () => void) {
        const previousState = this.disabled;
        this.disabled = true;
        try {
            action();
        } finally {
            this.disabled = previousState;
            onFinally();
        }
    }
}

export class PropertyHistoryRecord implements IHistoryRecord {
    readonly name: string;
    constructor(
        readonly object: any,
        readonly property: string | symbol | number,
        readonly oldValue: any,
        readonly newValue: any,
    ) {
        this.name = `change ${String(property)} property`;
    }

    dispose(): void {}

    undo(): void {
        this.object[this.property] = this.oldValue;
    }

    redo(): void {
        this.object[this.property] = this.newValue;
    }
}

export type NodeAction = "add" | "remove" | "move" | "transfer" | "insertAfter" | "insertBefore";

export interface NodeRecord {
    node: INode;
    action: NodeAction;
    oldParent?: INodeLinkedList;
    oldPrevious?: INode;
    newParent?: INodeLinkedList;
    newPrevious?: INode;
}

export class NodeLinkedListHistoryRecord implements IHistoryRecord {
    readonly name: string;

    constructor(readonly records: NodeRecord[]) {
        this.name = "change node";
    }

    dispose(): void {
        this.records.forEach((record) => {
            if (record.action === "remove") {
                record.node.dispose();
            }
        });
        this.records.length = 0;
    }

    // A recorded anchor can go stale over time (e.g. the node was removed outside of the
    // history); fall back to undefined so the node at least returns to the target parent
    // instead of the move being silently skipped.
    private static normalizePrevious(
        previous: INode | undefined,
        parent: INodeLinkedList | undefined,
    ): INode | undefined {
        return previous?.parent === parent ? previous : undefined;
    }

    private handleUndo(record: NodeRecord): void {
        switch (record.action) {
            case "add":
                record.newParent?.remove(record.node);
                break;
            case "remove":
                record.oldParent?.add(record.node);
                break;
            case "transfer":
                record.oldParent?.add(record.node);
                break;
            case "move":
                record.newParent?.move(
                    record.node,
                    record.oldParent!,
                    NodeLinkedListHistoryRecord.normalizePrevious(record.oldPrevious, record.oldParent),
                );
                break;
            case "insertAfter":
                record.newParent?.remove(record.node);
                break;
            case "insertBefore":
                record.newParent?.remove(record.node);
                break;
        }
    }

    private handleRedo(record: NodeRecord): void {
        switch (record.action) {
            case "add":
                record.newParent?.add(record.node);
                break;
            case "remove":
                record.oldParent?.remove(record.node);
                break;
            case "transfer":
                record.oldParent?.transfer(record.node);
                break;
            case "move":
                record.oldParent?.move(
                    record.node,
                    record.newParent!,
                    NodeLinkedListHistoryRecord.normalizePrevious(record.newPrevious, record.newParent),
                );
                break;
            case "insertAfter":
                record.newParent?.insertAfter(record.newPrevious, record.node);
                break;
            case "insertBefore":
                record.newParent?.insertBefore(record.newPrevious?.nextSibling, record.node);
                break;
        }
    }

    undo(): void {
        for (let i = this.records.length - 1; i >= 0; i--) {
            this.handleUndo(this.records[i]);
        }
    }

    redo(): void {
        this.records.forEach((record) => this.handleRedo(record));
    }
}

export class ArrayRecord implements IHistoryRecord {
    readonly records: Array<IHistoryRecord> = [];

    constructor(readonly name: string) {}

    dispose(): void {
        this.records.forEach((r) => r.dispose());
    }

    undo() {
        for (let index = this.records.length - 1; index >= 0; index--) {
            this.records[index].undo();
        }
    }

    redo() {
        for (const record of this.records) {
            record.redo();
        }
    }
}

import type { Patches } from 'mutative';
import { TravelsTypeError } from '../errors.js';
import type { PatchesOption, TravelPatches } from '../type.js';
import { findStateCompatibilityIssues } from '../compatibility.js';
import { deepCloneValue } from './patch-utils.js';

type HistoryViewInput<S, P extends PatchesOption> = {
  state: S;
  position: number;
  patches: TravelPatches<P>;
  maxHistory: number;
  manualMode: boolean;
  apply: (state: S, patches: Patches<P>) => S;
};

/** Reconstructs, caches, and safely snapshots visible history states. */
export class HistoryView<S, P extends PatchesOption = {}> {
  private cache: { version: number; history: S[] } | null = null;
  private revision = 0;

  public get version(): number {
    return this.revision;
  }

  public invalidate(): void {
    this.revision += 1;
    this.cache = null;
  }

  public get(input: HistoryViewInput<S, P>): readonly S[] {
    if (this.cache?.version === this.revision) {
      return this.cache.history;
    }

    let currentState = input.state;
    const patches =
      input.manualMode && input.patches.patches.length > input.maxHistory
        ? input.patches.patches.slice(
            input.patches.patches.length - input.maxHistory
          )
        : input.patches.patches;
    const inversePatches =
      input.manualMode &&
      input.patches.inversePatches.length > input.maxHistory
        ? input.patches.inversePatches.slice(
            input.patches.inversePatches.length - input.maxHistory
          )
        : input.patches.inversePatches;

    const futureHistory: S[] = [];
    for (let index = input.position; index < patches.length; index += 1) {
      currentState = input.apply(currentState, patches[index]);
      futureHistory.push(currentState);
    }

    currentState = input.state;
    const pastHistory: S[] = [];
    for (let index = input.position - 1; index > -1; index -= 1) {
      currentState = input.apply(currentState, inversePatches[index]);
      pastHistory.push(currentState);
    }
    pastHistory.reverse();

    const history = [...pastHistory, input.state, ...futureHistory];
    this.cache = { version: this.revision, history };

    if (process.env.NODE_ENV !== 'production') {
      Object.freeze(history);
    }

    return history;
  }

  public snapshot(history: readonly S[]): S[] {
    const issues: string[] = [];
    for (
      let index = 0;
      index < history.length && issues.length < 20;
      index += 1
    ) {
      for (const issue of findStateCompatibilityIssues(history[index], {
        allowFrozen: true,
        maxIssues: 20 - issues.length,
      })) {
        const path =
          issue.path === '$'
            ? `$.history[${index}]`
            : `$.history[${index}]${issue.path.slice(1)}`;
        issues.push(`${path}: ${issue.message}`);
      }
    }

    if (issues.length > 0) {
      throw new TravelsTypeError(
        'PERSISTENCE_INCOMPATIBLE',
        `Travels: getHistorySnapshot cannot detach non-durable history:\n- ${issues.join(
          '\n- '
        )}`
      );
    }

    return history.map((state) => deepCloneValue(state) as S);
  }
}

import { describe, expect, test } from 'vitest';
import { createTravels } from '../src/index';

describe('history patch replay ordering', () => {
  test.each([true, false])(
    'restores array length assignments with pathAsArray=%s',
    (pathAsArray) => {
      const initial = { items: [1, 2, 3, 4] };
      const travels = createTravels(initial, {
        patchesOptions: { pathAsArray },
      });

      travels.setState((draft) => {
        draft.items.length = 1;
      });

      expect(travels.getState()).toEqual({ items: [1] });
      expect(travels.getHistory()).toEqual([initial, { items: [1] }]);

      travels.back();
      expect(travels.getState()).toEqual(initial);

      travels.forward();
      expect(travels.getState()).toEqual({ items: [1] });
    }
  );

  test('matches the recorded model at every position', () => {
    const initial = {
      items: [1, 2, 3, 4],
      nested: { enabled: false, label: 'initial' },
    };
    const travels = createTravels(initial, { maxHistory: 10 });
    const snapshots = [initial];

    travels.setState((draft) => {
      draft.items.length = 2;
      draft.nested.enabled = true;
    });
    snapshots.push({
      items: [1, 2],
      nested: { enabled: true, label: 'initial' },
    });

    travels.setState((draft) => {
      draft.items.splice(0, 1, 9, 8);
      draft.nested.label = 'updated';
    });
    snapshots.push({
      items: [9, 8, 2],
      nested: { enabled: true, label: 'updated' },
    });

    travels.setState((draft) => {
      draft.items.length = 1;
      delete (draft.nested as { enabled: boolean; label?: string }).label;
    });
    snapshots.push({
      items: [9],
      nested: { enabled: true },
    } as (typeof snapshots)[number]);

    expect(travels.getHistory()).toEqual(snapshots);

    for (let position = snapshots.length - 1; position >= 0; position -= 1) {
      travels.go(position);
      expect(travels.getState()).toEqual(snapshots[position]);
      expect(travels.getHistory()[position]).toEqual(travels.getState());
    }

    for (let position = 0; position < snapshots.length; position += 1) {
      travels.go(position);
      expect(travels.getState()).toEqual(snapshots[position]);
    }
  });
});

